import pytest


def max_drawdown(prices):
    if not prices:
        raise ValueError("need at least one price")
    if min(prices) <= 0:
        raise ValueError("prices must be positive")
    peak, worst = prices[0], 0.0
    for p in prices:
        peak = max(peak, p)
        worst = min(worst, p / peak - 1)
    return worst

def test_empty_prices_raise():
    with pytest.raises(ValueError, match="at least one"):
        max_drawdown([])

def test_negative_price_raises():
    with pytest.raises(ValueError, match="positive"):
        max_drawdown([100.00, -5.00])

def test_drawdown_by_hand():
    assert max_drawdown([100.00, 120.00, 90.00]) == pytest.approx(-0.25)

